fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    let n = list.len();
    // Problem statement guarantees: 1 <= k < n
    debug_assert!(n > 0);
    debug_assert!(k >= 1 && k < n);

    let idx = k - 1; // convert to 0-based index
    let mut new_list = Vec::with_capacity(n - 1);

    // Copy prefix [0..idx)
    new_list.extend_from_slice(&list[..idx]);
    // Copy suffix (idx removed) => [idx+1..n)
    new_list.extend_from_slice(&list[idx + 1..]);

    new_list
}

